input.command:
cd /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/skill-drafts-page/build && cat > 01-head.html <<'EOF'
<title>Held rule drafts</title>
<meta name="claude:viewport-fit-sides" content="cover">
<meta name="description" content="The skill writer's drafts of your held rules of 27 to 29 October, each as the current text beside the new text, for your yes or no: 20 rules of yours, three proposals of the coordinator and the commit trailer.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:ital,wght@0,400;0,700;1,400&family=JetBrains+Mono:wght@400;600&display=swap">
EOF
cat > 02-style2.html <<'EOF'
<style>
:root { --cut-bg: #f6e0da; --cut-rule: #a8453a; --add-bg: #dcefe5; --add-rule: #1f6f5c; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  --cut-bg: #3b2621; --cut-rule: #e08a7d; --add-bg: #1d3a2f; --add-rule: #6cc4a8 } }
:root[data-theme="dark"] { --cut-bg: #3b2621; --cut-rule: #e08a7d; --add-bg: #1d3a2f; --add-rule: #6cc4a8 }
nav.parts ul { columns: 2 16rem; margin: 0 0 .6rem; padding-left: 0; list-style: none; }
nav.parts ul li { break-inside: avoid; }
nav.parts h3 { font-size: .9rem; margin: .7rem 0 .2rem; color: var(--muted); }
ol.points { padding-left: 1.6rem; }
ol.points > li { margin-bottom: .7rem; }
ol.points > li > p { margin: 0 0 .35rem; }
dl.gloss { margin: 0; }
dl.gloss dt { font-weight: 700; margin-top: .5em; }
dl.gloss dd { margin: .1em 0 0 1.5em; max-width: 65ch; }
blockquote.held { margin: .3rem 0 .5rem; padding: .1rem 0 .1rem .8rem; border-left: 3px solid var(--rule); }
blockquote.held p { margin: 0 0 .3rem; }
.note { background: var(--note-bg); border-left: 3px solid var(--note-rule); padding: .5rem .75rem; margin: 0 0 .8rem; border-radius: 0 4px 4px 0; max-width: 65ch; }
.where-in { font-family: var(--mono); font-size: .76rem; color: var(--muted); margin: .7rem 0 .25rem; }
.change { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin: .3rem 0 .5rem; }
.change.solo { grid-template-columns: minmax(0, 1fr); }
.change > div { background: var(--surface); border: 1px solid var(--rule); border-radius: 6px; padding: .55rem .75rem; min-width: 0; }
.change .side { display: block; font-family: var(--mono); font-size: .72rem; font-weight: 600; color: var(--muted); letter-spacing: .02em; margin-bottom: .3rem; }
.change p, .change li { font-size: .95rem; max-width: none; }
.change p { margin: 0 0 .4rem; }
.change ul, .change ol { margin: 0 0 .4rem; }
.change pre { font-family: var(--mono); font-size: .8rem; background: var(--code-bg); padding: .4rem .5rem; border-radius: 4px; white-space: pre-wrap; overflow-wrap: anywhere; margin: .3rem 0 .5rem; }
.cut { background: var(--cut-bg); text-decoration: line-through; text-decoration-color: var(--cut-rule); }
.add { background: var(--add-bg); text-decoration: underline; text-decoration-color: var(--add-rule); text-underline-offset: .15em; }
@media (max-width: 40rem) { .change { grid-template-columns: minmax(0, 1fr); } }
</style>
EOF
echo ok

